package dk.stream.android;
import org.junit.Test;
import org.json.*;
import java.nio.file.*;
import java.util.*;
import static org.junit.Assert.*;
public class LanguageAndPermissionsTest {
 private Map<String,String> dictionary()throws Exception{JSONObject json=new JSONObject(new String(Files.readAllBytes(Paths.get("src/main/assets/ui_en.json")),java.nio.charset.StandardCharsets.UTF_8));Map<String,String> result=new HashMap<>();Iterator<String> keys=json.keys();while(keys.hasNext()){String key=keys.next();result.put(key,json.getString(key));}return result;}
 @Test public void translatesCoreScreensWithoutChangingUserContent()throws Exception{Map<String,String> map=dictionary();assertEquals("Home",UiText.translate("Forside",map));assertEquals("Local files",UiText.translate("Lokale filer",map));assertEquals("Favorites",UiText.translate("Favoritter",map));assertEquals("Metallica – One",UiText.translate("Metallica – One",map));assertEquals("https://example.com/Musik",UiText.translate("https://example.com/Musik",map));assertEquals("",UiText.translate("",map));}
 @Test public void dynamicMessagesKeepFilenamesAndTranslateAppText()throws Exception{Map<String,String> map=dictionary();assertEquals("Download complete: Bæltestedet.mp3",UiText.translate("Download færdig: Bæltestedet.mp3",map));assertEquals("37 % downloaded · Afsnit.mp3",UiText.translate("37 % hentet · Afsnit.mp3",map));assertEquals("8 favorites",UiText.translate("8 favoritter",map));assertEquals("Record TV2?\n\nThe recording will be saved to Downloads. You cannot change channels or close the app using Back until recording stops.",UiText.translate("Vil du optage TV2?\n\nOptagelsen gemmes i Download. Du kan ikke skifte kanal eller lukke appen med tilbage-knappen, før optagelsen er stoppet.",map));}
 @Test public void languageRoundTripsWithoutTranslatingSavedPageIds()throws Exception{Library library=new Library();library.appLanguage="en";library.pageFavorites.put("Musik",true);Library restored=SettingsBackup.decode(new java.io.ByteArrayInputStream(SettingsBackup.encode(library)));assertEquals("en",restored.appLanguage);assertTrue(restored.pageFavorites.get("Musik"));assertEquals(Arrays.asList(FavoriteHomeOrder.NAMES),restored.favoriteHomeOrder);}
 @Test public void unsupportedLanguageDefaultsToDanish(){assertEquals("da",AppLanguage.normalize("fr"));assertEquals("en",AppLanguage.normalize("en"));}
 @Test public void startupRequestsOnlyApplicableRuntimePermissions(){assertArrayEquals(new String[]{"android.permission.WRITE_EXTERNAL_STORAGE"},StartupPermissions.forVersion(28));assertArrayEquals(new String[0],StartupPermissions.forVersion(29));assertArrayEquals(new String[]{"android.permission.POST_NOTIFICATIONS"},StartupPermissions.forVersion(33));assertArrayEquals(new String[]{"android.permission.POST_NOTIFICATIONS","android.permission.ACCESS_LOCAL_NETWORK"},StartupPermissions.forVersion(37));}
 @Test public void freshInstallHasOnlyBuiltInSourcesAndAllHomeButtons(){Library library=new Library();assertTrue(library.sources.isEmpty());assertTrue(library.localFiles.isEmpty());assertNull(library.pcloud);assertFalse(library.openSpotApiUrl.isEmpty());assertTrue(library.miniPlayer);assertTrue(library.dailyGuideUpdate);assertTrue(library.hiddenHomeButtons.isEmpty());assertEquals(StartupPages.HOME,StartupPages.selected(library));assertEquals(AndroidAutoPages.ROOT,library.androidAutoStartPage);}
 @Test public void englishResourcesCoverAllDefaultStringsAndFormatArguments()throws Exception{javax.xml.parsers.DocumentBuilder builder=javax.xml.parsers.DocumentBuilderFactory.newInstance().newDocumentBuilder();org.w3c.dom.Document defaults=builder.parse("src/main/res/values/strings.xml"),english=builder.parse("src/main/res/values-en/strings.xml");Map<String,String> values=new HashMap<>();org.w3c.dom.NodeList translated=english.getElementsByTagName("string");for(int i=0;i<translated.getLength();i++){org.w3c.dom.Element item=(org.w3c.dom.Element)translated.item(i);values.put(item.getAttribute("name"),item.getTextContent());}org.w3c.dom.NodeList originals=defaults.getElementsByTagName("string");for(int i=0;i<originals.getLength();i++){org.w3c.dom.Element item=(org.w3c.dom.Element)originals.item(i);String key=item.getAttribute("name");assertTrue(key,values.containsKey(key));java.util.regex.Matcher placeholders=java.util.regex.Pattern.compile("%[0-9]+\\$[sdf]").matcher(item.getTextContent());while(placeholders.find())assertTrue(key,values.get(key).contains(placeholders.group()));}}
 @Test public void savedDisabledDefaultsArePreserved()throws Exception{Library library=new Library();library.dailyGuideUpdate=false;library.miniPlayer=false;library.hiddenHomeButtons.add("Film");library.androidAutoStartPage=AndroidAutoPages.MUSIC;Library restored=Library.fromJson(library.toJson());assertFalse(restored.dailyGuideUpdate);assertFalse(restored.miniPlayer);assertTrue(restored.hiddenHomeButtons.contains("Film"));assertEquals(AndroidAutoPages.MUSIC,restored.androidAutoStartPage);}
}
